#include <M5Unified.h>
#include <esp_heap_caps.h>

extern "C" {
#include "core/canvas.h"
#include "hacks/registry.h"
#include "runner/hack_runner.h"
}

static const int kSize = 466;
static const uint32_t kSliceUs = 10000;
static const uint32_t kStatsEveryMs = 5000;

static Canvas canvas;
static HackRunner *runner;
static uint32_t frames;
static uint32_t statsAt;

static void halt(const char *msg) {
  Serial.println(msg);
  M5.Display.fillScreen(0x000000);
  M5.Display.setTextColor(0xFFFFFF);
  M5.Display.setTextDatum(middle_center);
  M5.Display.drawString(msg, M5.Display.width() / 2, M5.Display.height() / 2);
  for (;;) delay(1000);
}

static void printStats(const char *tag) {
  Serial.printf("%s %s fps=%.1f heap=%u psram=%u\n", tag,
                g_hacks[runner_index(runner)]->name,
                frames * 1000.0f / kStatsEveryMs, (unsigned)ESP.getFreeHeap(),
                (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
}

static void pollButtons() {
  bool switched = false;
  if (M5.BtnA.wasPressed()) {
    runner_next(runner);
    switched = true;
  }
  if (M5.BtnB.wasPressed()) {
    runner_prev(runner);
    switched = true;
  }
  if (switched) {
    Serial.printf("switch -> %s heap=%u psram=%u\n",
                  g_hacks[runner_index(runner)]->name,
                  (unsigned)ESP.getFreeHeap(),
                  (unsigned)heap_caps_get_free_size(MALLOC_CAP_SPIRAM));
    frames = 0;
    statsAt = millis();
  }
}

void setup() {
  auto cfg = M5.config();
  M5.begin(cfg);
  Serial.begin(115200);
  M5.Display.setSwapBytes(false);

  if (canvas_init(&canvas, kSize, kSize, ps_malloc) != 0)
    halt("PSRAM alloc failed");
  runner = runner_create(&canvas);
  if (!runner || runner_start(runner, 0) != 0) halt("hack start failed");
  printStats("boot");
  statsAt = millis();
}

void loop() {
  M5.update();
  pollButtons();

  unsigned long delayUs = runner_step(runner);
  M5.Display.pushImage(0, 0, kSize, kSize, canvas.px);
  frames++;

  uint32_t waitedUs = 0;
  while (waitedUs < delayUs) {
    uint32_t slice = delayUs - waitedUs < kSliceUs ? delayUs - waitedUs : kSliceUs;
    delayMicroseconds(slice);
    waitedUs += slice;
    M5.update();
    pollButtons();
  }

  if (millis() - statsAt >= kStatsEveryMs) {
    printStats("run");
    frames = 0;
    statsAt = millis();
  }
}
#include "runner/hack_runner.h"

#include <stdlib.h>

#include "hacks/registry.h"
#include "x11shim/xshim.h"

#define RUNNER_WINDOW ((Window)1)

struct HackRunner {
  Canvas *canvas;
  Display *dpy;
  const HackEntry *const *hacks;
  int count;
  int index;
  void *closure;
  int running;
};

HackRunner *runner_create_with(Canvas *canvas, const HackEntry *const *hacks,
                               int count) {
  HackRunner *r = (HackRunner *)calloc(1, sizeof(*r));
  if (!r) return NULL;
  r->canvas = canvas;
  r->dpy = xshim_open_display(canvas);
  r->hacks = hacks;
  r->count = count;
  if (!r->dpy) {
    free(r);
    return NULL;
  }
  return r;
}

HackRunner *runner_create(Canvas *canvas) {
  return runner_create_with(canvas, g_hacks, g_hack_count);
}

static void stop(HackRunner *r) {
  if (!r->running) return;
  r->hacks[r->index]->free(r->dpy, RUNNER_WINDOW, r->closure);
  r->closure = NULL;
  r->running = 0;
}

void runner_destroy(HackRunner *r) {
  if (!r) return;
  stop(r);
  xshim_close_display(r->dpy);
  free(r);
}

int runner_start(HackRunner *r, int index) {
  if (index < 0 || index >= r->count) return -1;
  stop(r);
  r->index = index;
  canvas_clear(r->canvas, 0);
  xshim_set_defaults(r->hacks[index]->defaults);
  r->closure = r->hacks[index]->init(r->dpy, RUNNER_WINDOW);
  r->running = 1;
  return 0;
}

unsigned long runner_step(HackRunner *r) {
  if (!r->running) return RUNNER_MAX_DELAY_US;
  unsigned long d = r->hacks[r->index]->draw(r->dpy, RUNNER_WINDOW, r->closure);
  if (d < RUNNER_MIN_DELAY_US) return RUNNER_MIN_DELAY_US;
  if (d > RUNNER_MAX_DELAY_US) return RUNNER_MAX_DELAY_US;
  return d;
}

int runner_next(HackRunner *r) {
  runner_start(r, (r->index + 1) % r->count);
  return r->index;
}

int runner_prev(HackRunner *r) {
  runner_start(r, (r->index + r->count - 1) % r->count);
  return r->index;
}

int runner_index(const HackRunner *r) { return r->index; }
#include "x11shim/xshim.h"

#include <stdlib.h>

Bool mono_p = False;
const char *progname = "stopwatch-screensaver";

Display *xshim_open_display(Canvas *canvas) {
  Display *dpy = (Display *)calloc(1, sizeof(*dpy));
  if (dpy) dpy->canvas = canvas;
  return dpy;
}

void xshim_close_display(Display *dpy) { free(dpy); }

GC XCreateGC(Display *dpy, Drawable d, unsigned long mask, XGCValues *v) {
  (void)dpy;
  (void)d;
  GC gc = (GC)calloc(1, sizeof(*gc));
  if (gc) gc->foreground = (mask & GCForeground) ? v->foreground : 0xFFFF;
  return gc;
}

int XFreeGC(Display *dpy, GC gc) {
  (void)dpy;
  free(gc);
  return 0;
}

int XSetForeground(Display *dpy, GC gc, unsigned long pixel) {
  (void)dpy;
  gc->foreground = pixel;
  return 0;
}

Status XGetWindowAttributes(Display *dpy, Window w, XWindowAttributes *a) {
  (void)w;
  a->x = a->y = 0;
  a->width = dpy->canvas->w;
  a->height = dpy->canvas->h;
  a->depth = 16;
  a->visual = NULL;
  a->screen = NULL;
  a->colormap = 1;
  return 1;
}

int XClearWindow(Display *dpy, Window w) {
  (void)w;
  canvas_clear(dpy->canvas, 0);
  return 0;
}

int XDrawPoint(Display *dpy, Drawable d, GC gc, int x, int y) {
  (void)d;
  canvas_point(dpy->canvas, x, y, (uint16_t)gc->foreground);
  return 0;
}

int XDrawLine(Display *dpy, Drawable d, GC gc, int x1, int y1, int x2,
              int y2) {
  (void)d;
  canvas_line(dpy->canvas, x1, y1, x2, y2, (uint16_t)gc->foreground);
  return 0;
}

int XDrawLines(Display *dpy, Drawable d, GC gc, XPoint *pts, int n, int mode) {
  (void)mode;
  for (int i = 1; i < n; i++)
    XDrawLine(dpy, d, gc, pts[i - 1].x, pts[i - 1].y, pts[i].x, pts[i].y);
  return 0;
}

int XFillRectangle(Display *dpy, Drawable d, GC gc, int x, int y,
                   unsigned int w, unsigned int h) {
  (void)d;
  canvas_fill_rect(dpy->canvas, x, y, w > 0x7FFFFFFF ? 0x7FFFFFFF : (int)w,
                   h > 0x7FFFFFFF ? 0x7FFFFFFF : (int)h,
                   (uint16_t)gc->foreground);
  return 0;
}

int XFillArc(Display *dpy, Drawable d, GC gc, int x, int y, unsigned int w,
             unsigned int h, int angle1, int angle2) {
  (void)d;
  (void)angle1;
  if (angle2 < 360 * 64) return 0;
  canvas_fill_ellipse(dpy->canvas, x, y, w > 0x7FFFFFFF ? 0x7FFFFFFF : (int)w,
                      h > 0x7FFFFFFF ? 0x7FFFFFFF : (int)h,
                      (uint16_t)gc->foreground);
  return 0;
}

int XFillPolygon(Display *dpy, Drawable d, GC gc, XPoint *pts, int n,
                 int shape, int mode) {
  (void)d;
  (void)shape;
  (void)mode;
  if (n < 3 || n > 256) return 0;
  int xy[512];
  for (int i = 0; i < n; i++) {
    xy[2 * i] = pts[i].x;
    xy[2 * i + 1] = pts[i].y;
  }
  canvas_fill_polygon(dpy->canvas, xy, n, (uint16_t)gc->foreground);
  return 0;
}

Status XAllocColor(Display *dpy, Colormap cmap, XColor *c) {
  (void)dpy;
  (void)cmap;
  c->pixel = rgb565_from16(c->red, c->green, c->blue);
  return 1;
}

int XFreeColors(Display *dpy, Colormap cmap, unsigned long *pixels, int n,
                unsigned long planes) {
  (void)dpy;
  (void)cmap;
  (void)pixels;
  (void)n;
  (void)planes;
  return 0;
}
#include "core/canvas.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

/* The ESP32 has a 32-bit long; clip arithmetic needs 64 bits to be safe. */
typedef int64_t wide_t;

int canvas_init(Canvas *c, int w, int h, void *(*alloc)(size_t)) {
  c->w = w;
  c->h = h;
  c->px = (uint16_t *)alloc((size_t)w * (size_t)h * sizeof(uint16_t));
  if (!c->px) return -1;
  memset(c->px, 0, (size_t)w * (size_t)h * sizeof(uint16_t));
  return 0;
}

void canvas_free(Canvas *c) {
  free(c->px);
  c->px = NULL;
}

uint16_t rgb565(uint8_t r, uint8_t g, uint8_t b) {
  return (uint16_t)(((r & 0xF8) << 8) | ((g & 0xFC) << 3) | (b >> 3));
}

uint16_t rgb565_from16(uint16_t r, uint16_t g, uint16_t b) {
  return rgb565((uint8_t)(r >> 8), (uint8_t)(g >> 8), (uint8_t)(b >> 8));
}

void canvas_clear(Canvas *c, uint16_t color) {
  for (int i = 0, n = c->w * c->h; i < n; i++) c->px[i] = color;
}

void canvas_point(Canvas *c, int x, int y, uint16_t color) {
  if (x < 0 || y < 0 || x >= c->w || y >= c->h) return;
  c->px[(size_t)y * c->w + x] = color;
}

static void hspan(Canvas *c, wide_t x0, wide_t x1, wide_t y, uint16_t color) {
  if (y < 0 || y >= c->h || x1 < 0 || x0 >= c->w) return;
  if (x0 < 0) x0 = 0;
  if (x1 >= c->w) x1 = c->w - 1;
  uint16_t *row = c->px + (size_t)y * c->w;
  for (int x = (int)x0, last = (int)x1; x <= last; x++) row[x] = color;
}

void canvas_fill_rect(Canvas *c, int x, int y, int w, int h, uint16_t color) {
  if (w <= 0 || h <= 0) return;
  wide_t x1 = (wide_t)x + w - 1, y1 = (wide_t)y + h - 1;
  wide_t y0 = y < 0 ? 0 : y;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) hspan(c, x, x1, yy, color);
}

/* Liang-Barsky clip of the segment to [0,w-1]x[0,h-1]; false if outside. */
static int clip_line(const Canvas *c, double *x0, double *y0, double *x1,
                     double *y1) {
  double dx = *x1 - *x0, dy = *y1 - *y0, t0 = 0, t1 = 1;
  double p[4] = {-dx, dx, -dy, dy};
  double q[4] = {*x0, (c->w - 1) - *x0, *y0, (c->h - 1) - *y0};
  for (int i = 0; i < 4; i++) {
    if (p[i] == 0) {
      if (q[i] < 0) return 0;
    } else {
      double t = q[i] / p[i];
      if (p[i] < 0) {
        if (t > t1) return 0;
        if (t > t0) t0 = t;
      } else {
        if (t < t0) return 0;
        if (t < t1) t1 = t;
      }
    }
  }
  double ax = *x0, ay = *y0;
  *x0 = ax + t0 * dx;
  *y0 = ay + t0 * dy;
  *x1 = ax + t1 * dx;
  *y1 = ay + t1 * dy;
  return 1;
}

void canvas_line(Canvas *c, int x0, int y0, int x1, int y1, uint16_t color) {
  double ax = x0, ay = y0, bx = x1, by = y1;
  int clipped = x0 < 0 || y0 < 0 || x0 >= c->w || y0 >= c->h || x1 < 0 ||
                y1 < 0 || x1 >= c->w || y1 >= c->h;
  if (clipped) {
    if (!clip_line(c, &ax, &ay, &bx, &by)) return;
    ax = floor(ax + 0.5);
    ay = floor(ay + 0.5);
    bx = floor(bx + 0.5);
    by = floor(by + 0.5);
  }
  int ix0 = (int)ax, iy0 = (int)ay, ix1 = (int)bx, iy1 = (int)by;
  int dx = abs(ix1 - ix0), sx = ix0 < ix1 ? 1 : -1;
  int dy = -abs(iy1 - iy0), sy = iy0 < iy1 ? 1 : -1;
  int err = dx + dy;
  for (;;) {
    canvas_point(c, ix0, iy0, color);
    if (ix0 == ix1 && iy0 == iy1) break;
    int e2 = 2 * err;
    if (e2 >= dy) {
      err += dy;
      ix0 += sx;
    }
    if (e2 <= dx) {
      err += dx;
      iy0 += sy;
    }
  }
}

void canvas_fill_ellipse(Canvas *c, int x, int y, int w, int h,
                         uint16_t color) {
  if (w <= 0 || h <= 0) return;
  double cx = x + (w - 1) / 2.0, cy = y + (h - 1) / 2.0;
  double rx = w / 2.0, ry = h / 2.0;
  wide_t y0 = y < 0 ? 0 : y, y1 = (wide_t)y + h - 1;
  if (y1 >= c->h) y1 = c->h - 1;
  for (wide_t yy = y0; yy <= y1; yy++) {
    double ny = (yy - cy) / ry;
    double t = 1.0 - ny * ny;
    if (t < 0) continue;
    double half = rx * sqrt(t);
    wide_t xa = (wide_t)ceil(cx - half), xb = (wide_t)floor(cx + half);
    if (xb < xa) continue;
    hspan(c, xa, xb, yy, color);
  }
}

void canvas_fill_polygon(Canvas *c, const int *xy, int n, uint16_t color) {
  if (n < 3) return;
  wide_t ymin = xy[1], ymax = xy[1];
  for (int i = 1; i < n; i++) {
    if (xy[2 * i + 1] < ymin) ymin = xy[2 * i + 1];
    if (xy[2 * i + 1] > ymax) ymax = xy[2 * i + 1];
  }
  if (ymin < 0) ymin = 0;
  if (ymax >= c->h) ymax = c->h - 1;
  for (wide_t yy = ymin; yy <= ymax; yy++) {
    double xs[64];
    int nx = 0;
    double sy = yy + 0.5;
    for (int i = 0, j = n - 1; i < n; j = i++) {
      double yi = xy[2 * i + 1], yj = xy[2 * j + 1];
      if ((yi <= sy && yj > sy) || (yj <= sy && yi > sy)) {
        double t = (sy - yi) / (yj - yi);
        if (nx < 64) xs[nx++] = xy[2 * i] + t * (xy[2 * j] - xy[2 * i]);
      }
    }
    for (int a = 1; a < nx; a++)
      for (int b = a; b > 0 && xs[b - 1] > xs[b]; b--) {
        double tmp = xs[b];
        xs[b] = xs[b - 1];
        xs[b - 1] = tmp;
      }
    for (int k = 0; k + 1 < nx; k += 2)
      hspan(c, (wide_t)ceil(xs[k] - 0.5), (wide_t)ceil(xs[k + 1] - 0.5) - 1, yy,
            color);
  }
}

