"""Fetch and extract the latest xscreensaver source into vendor/.

Run with: uv run tools/fetch_xscreensaver.py [--version X.YY] [--force]
"""

import argparse
import hashlib
import re
import shutil
import sys
import tarfile
import tempfile
import urllib.error
import urllib.request
from pathlib import Path, PurePosixPath

BASE_URL = "https://www.jwz.org/xscreensaver/"
DOWNLOAD_PAGE = BASE_URL + "download.html"
SURVEYED_VERSION = "6.16"
USER_AGENT = "stopwatch-screensaver-fetch/1.0 (personal project; fetches xscreensaver source)"
TARBALL_LINK = re.compile(
    r"""href=["']?xscreensaver-(\d+(?:\.\d+)+)\.tar\.gz""", re.IGNORECASE
)


class FetchError(Exception):
    pass


def _version_key(version: str) -> tuple[int, ...]:
    return tuple(int(p) for p in version.split("."))


def find_versions(html: str) -> list[str]:
    return sorted(set(TARBALL_LINK.findall(html)), key=_version_key)


def pick_version(html: str, wanted: str | None) -> str:
    versions = find_versions(html)
    if not versions:
        raise FetchError("no xscreensaver tarball link found on the download page")
    if wanted is None:
        return versions[-1]
    if wanted not in versions:
        raise FetchError(f"version {wanted} not listed (found: {', '.join(versions)})")
    return wanted


def safe_extract(tar_path: Path, dest: Path) -> Path:
    with tarfile.open(tar_path) as tar:
        tops = set()
        for member in tar.getmembers():
            name = PurePosixPath(member.name)
            if name.is_absolute() or ".." in name.parts:
                raise FetchError(f"unsafe path in tarball: {member.name}")
            if name.parts:
                tops.add(name.parts[0])
        if len(tops) != 1:
            raise FetchError(f"expected one top-level directory, found {sorted(tops)}")
        try:
            tar.extractall(dest, filter="data")
        except (tarfile.TarError, OSError) as err:
            raise FetchError(f"unsafe tarball: {err}") from err
    return dest / tops.pop()


def _open(url: str, timeout: int):
    request = urllib.request.Request(url, headers={"User-Agent": USER_AGENT})
    return urllib.request.urlopen(request, timeout=timeout)


def fetch_text(url: str) -> str:
    try:
        with _open(url, 30) as resp:
            return resp.read().decode("utf-8", "replace")
    except (urllib.error.URLError, TimeoutError) as err:
        raise FetchError(f"could not fetch {url}: {err}") from err


def download(url: str, target: Path) -> str:
    sha = hashlib.sha256()
    try:
        with _open(url, 60) as resp, target.open("wb") as out:
            while chunk := resp.read(1 << 16):
                sha.update(chunk)
                out.write(chunk)
    except (urllib.error.URLError, TimeoutError) as err:
        raise FetchError(f"could not download {url}: {err}") from err
    return sha.hexdigest()


def run(args: argparse.Namespace) -> None:
    version = pick_version(fetch_text(DOWNLOAD_PAGE), args.version)
    if version != SURVEYED_VERSION:
        print(
            f"warning: surveyed against {SURVEYED_VERSION}, fetching {version}; "
            "re-check the call survey and porting assessment",
            file=sys.stderr,
        )
    dest = Path(args.dest)
    target = dest / f"xscreensaver-{version}"
    if target.exists() and not args.force:
        print(f"xscreensaver-{version} already present at {target}, skipping")
        return
    url = f"{BASE_URL}xscreensaver-{version}.tar.gz"
    with tempfile.TemporaryDirectory() as tmp:
        tar_path = Path(tmp) / "xs.tar.gz"
        sha256 = download(url, tar_path)
        print(f"version {version}\nurl {url}\nsha256 {sha256}")
        extracted = safe_extract(tar_path, Path(tmp) / "x")
        dest.mkdir(parents=True, exist_ok=True)
        if target.exists():
            shutil.rmtree(target)
        shutil.move(str(extracted), str(target))
    print(f"extracted to {target}")


def main(argv: list[str]) -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--version", help="specific version, e.g. 6.16")
    parser.add_argument("--force", action="store_true", help="replace existing")
    parser.add_argument("--dest", default="vendor", help="default: vendor")
    args = parser.parse_args(argv)
    try:
        run(args)
    except FetchError as err:
        print(f"error: {err}", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"""Convert a raw little-endian RGB565 frame dump to PNG (stdlib only).

Run with: uv run tools/rgb565_to_png.py in.raw WIDTH HEIGHT out.png
"""

import struct
import sys
import zlib


def _chunk(kind: bytes, body: bytes) -> bytes:
    crc = zlib.crc32(kind + body) & 0xFFFFFFFF
    return struct.pack(">I", len(body)) + kind + body + struct.pack(">I", crc)


def convert(raw: bytes, w: int, h: int) -> bytes:
    if len(raw) != w * h * 2:
        raise ValueError(f"expected {w * h * 2} bytes for {w}x{h}, got {len(raw)}")
    pixels = struct.unpack(f"<{w * h}H", raw)
    rows = bytearray()
    for y in range(h):
        rows.append(0)
        for p in pixels[y * w : (y + 1) * w]:
            r, g, b = (p >> 11) & 0x1F, (p >> 5) & 0x3F, p & 0x1F
            rows += bytes((r << 3 | r >> 2, g << 2 | g >> 4, b << 3 | b >> 2))
    ihdr = struct.pack(">IIBBBBB", w, h, 8, 2, 0, 0, 0)
    return (
        b"\x89PNG\r\n\x1a\n"
        + _chunk(b"IHDR", ihdr)
        + _chunk(b"IDAT", zlib.compress(bytes(rows), 9))
        + _chunk(b"IEND", b"")
    )


def main(argv: list[str]) -> int:
    if len(argv) != 4:
        print(__doc__)
        return 2
    src, w, h, dst = argv[0], int(argv[1]), int(argv[2]), argv[3]
    with open(src, "rb") as f:
        png = convert(f.read(), w, h)
    with open(dst, "wb") as f:
        f.write(png)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
"""Score every xscreensaver hack for porting effort against the X11 shim.

Run with: uv run tools/score_hacks.py [--vendor DIR] [--out FILE]
"""

import argparse
import re
import subprocess
import sys
import tempfile
import textwrap
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

X_CALL = re.compile(r"\b(X[A-Z][A-Za-z0-9]*)\s*\(")
GL_IDENT = re.compile(r"\b(glBegin|glVertex\w*|glx\w+|GLX\w+)\b")
NOISE = re.compile(
    r"""/\*.*?\*/|//[^\n]*|"(?:\\.|[^"\\\n])*"|'(?:\\.|[^'\\\n])*'""", re.DOTALL
)
MATH_CALL = re.compile(r"\b(sin|cos|sqrt|pow)\s*\(")

FLAG_CALLS = {
    "pixmaps": {"XCreatePixmap", "XCopyArea"},
    "readback": {"XGetImage", "XGetPixel"},
    "xor": {"XSetFunction"},
    "text": {"XDrawString", "XLoadFont", "XLoadQueryFont"},
    "clipmask": {"XSetClipMask"},
}
MODULE_ENTRY = re.compile(r"\bXSCREENSAVER_MODULE(?:_2)?\s*\(")
MISSING_HEADER = re.compile(r"fatal error: '([^']+)' file not found")
ERROR_PATTERNS = (
    (re.compile(r"use of undeclared identifier '([^']+)'"), "{0}"),
    (re.compile(r"call to undeclared function '([^']+)'"), "{0}"),
    (re.compile(r"unknown type name '([^']+)'"), "{0}"),
    (re.compile(r"no member named '([^']+)' in '(?:struct )?([^']+)'"), "{1}.{0}"),
)
UNNAMED = re.compile(r"::\(unnamed[^)]*\)")
MAX_HEADER_STUBS = 25
FLOAT_HEAVY_THRESHOLD = 20
MAX_MEDIUM_MISSING = 4


def strip_noise(source: str) -> str:
    return NOISE.sub(lambda m: "\n" * m.group(0).count("\n") or " ", source)


def is_hack(source: str) -> bool:
    """A screensaver registers itself with XSCREENSAVER_MODULE; everything
    else in hacks/ is a model, a helper library or a command-line tool."""
    return bool(MODULE_ENTRY.search(strip_noise(source)))


def implemented_calls(header: str) -> set[str]:
    return set(X_CALL.findall(strip_noise(header)))


def used_calls(source: str) -> set[str]:
    return set(X_CALL.findall(strip_noise(source)))


def classify(path: Path, source: str) -> str:
    if "glx" in path.parts or GL_IDENT.search(strip_noise(source)):
        return "gl"
    return "2d"


def blockers_for(
    name: str, source: str, include_dirs: list[Path], cc: str = "cc"
) -> list[str]:
    """Syntax-check source against the shim headers and list what is missing.

    Missing headers are stubbed with empty files so the compiler keeps going
    and reports everything else too. The source is compiled from a temporary
    directory so quoted includes cannot pick up the real xscreensaver headers.
    """
    found: set[str] = set()
    with tempfile.TemporaryDirectory() as tmp_name:
        tmp = Path(tmp_name)
        stubs = tmp / "stubs"
        stubs.mkdir()
        src_path = tmp / f"{name}.c"
        src_path.write_text(source)
        cmd = [cc, "-fsyntax-only", "-w", "-ferror-limit=0"]
        cmd += [f"-I{d}" for d in include_dirs] + [f"-I{stubs}", str(src_path)]
        stderr = ""
        for _ in range(MAX_HEADER_STUBS):
            stderr = subprocess.run(cmd, capture_output=True, text=True).stderr
            missing = MISSING_HEADER.search(stderr)
            if not missing:
                break
            header = missing.group(1)
            found.add(header)
            (stubs / header).parent.mkdir(parents=True, exist_ok=True)
            (stubs / header).write_text("")
    for pattern, template in ERROR_PATTERNS:
        for match in pattern.finditer(stderr):
            found.add(UNNAMED.sub("", template.format(*match.groups())))
    return sorted(found)


def score(
    path: Path, source: str, provided: set[str], blockers: list[str] | None = None
) -> dict:
    clean = strip_noise(source)
    used = used_calls(source)
    missing = sorted(used - provided)
    kind = classify(path, source)
    flags = [name for name, calls in FLAG_CALLS.items() if used & calls]
    if len(MATH_CALL.findall(clean)) >= FLOAT_HEAVY_THRESHOLD:
        flags.append("float-heavy")
    if re.search(r'#\s*include\s*"xlockmore\.h"', source):
        flags.append("needs-xlockmore")
    gaps = sorted(set(missing) | set(blockers or []))
    if kind == "gl":
        effort = "XL"
    elif not gaps:
        effort = "S"
    elif len(gaps) > MAX_MEDIUM_MISSING or {"pixmaps", "readback"} & set(flags):
        effort = "L"
    else:
        effort = "M"
    return {
        "name": path.stem,
        "kind": kind,
        "effort": effort,
        "missing": missing,
        "gaps": gaps,
        "flags": flags,
        "loc": source.count("\n") + 1,
    }


def rank_missing(rows: list[dict], n: int) -> list[tuple[str, float, int]]:
    """Shim gaps ranked for 2D hacks. A hack with k gaps gives each 1/k, so
    gaps blocking nearly-ready hacks rank first."""
    weight: dict[str, float] = defaultdict(float)
    hacks: dict[str, int] = defaultdict(int)
    for row in rows:
        gaps = row.get("gaps", row["missing"])
        if row["kind"] != "2d" or not gaps:
            continue
        for call in gaps:
            weight[call] += 1 / len(gaps)
            hacks[call] += 1
    ranked = sorted(weight, key=lambda c: (-weight[c], c))
    return [(c, round(weight[c], 2), hacks[c]) for c in ranked[:n]]


def render_table(rows: list[dict]) -> str:
    lines = [
        "| Hack | Kind | Effort | Shim gaps | Flags | LOC |",
        "| --- | --- | --- | --- | --- | --- |",
    ]
    for r in sorted(rows, key=lambda r: (r["effort"], r["name"])):
        missing = ", ".join(r.get("gaps", r["missing"])) or "-"
        flags = ", ".join(r["flags"]) or "-"
        lines.append(
            f"| {r['name']} | {r['kind']} | {r['effort']} | {missing} | {flags} | {r['loc']} |"
        )
    return "\n".join(lines) + "\n"


def render_ranking(ranked: list[tuple[str, float, int]]) -> str:
    lines = ["| Gap | Score | 2D hacks needing it |", "| --- | --- | --- |"]
    lines += [f"| {c} | {s} | {h} |" for c, s, h in ranked]
    return "\n".join(lines) + "\n"


def render_excluded(names: list[str]) -> str:
    return textwrap.fill(", ".join(names), width=78) + "\n"


def scan(
    vendor: Path, provided: set[str], include_dirs: list[Path]
) -> tuple[list[dict], list[str]]:
    """Returns (scored hacks, names of excluded non-hack files)."""
    files = sorted((vendor / "hacks").glob("*.c")) + sorted(
        (vendor / "hacks" / "glx").glob("*.c")
    )
    all_sources = {p: p.read_text(errors="replace") for p in files}
    sources = {p: src for p, src in all_sources.items() if is_hack(src)}
    excluded = sorted(p.stem for p in all_sources if p not in sources)
    files = list(sources)

    def one(path: Path) -> dict:
        source = sources[path]
        blockers = None
        if classify(path, source) == "2d":
            blockers = blockers_for(path.stem, source, include_dirs)
        return score(path, source, provided, blockers)

    with ThreadPoolExecutor(max_workers=8) as pool:
        return list(pool.map(one, files)), excluded


def main(argv: list[str]) -> int:
    root = Path(__file__).resolve().parent.parent
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--vendor", default=str(next((root / "vendor").glob("xscreensaver-*"))))
    parser.add_argument("--header", default=str(root / "firmware/src/x11shim/xshim.h"))
    parser.add_argument(
        "--shim-include",
        action="append",
        help="include dir for the shim compile check (default: the firmware's)",
    )
    parser.add_argument("--intro", default=str(root / "tools/assessment_intro.md"))
    parser.add_argument("--measured", default=str(root / "tools/assessment_measured.md"))
    parser.add_argument("--out", default=str(root / "docs/porting-assessment.md"))
    args = parser.parse_args(argv)

    vendor = Path(args.vendor)
    version = vendor.name.removeprefix("xscreensaver-")
    includes = [Path(d) for d in args.shim_include] if args.shim_include else [
        root / "firmware/src",
        root / "firmware/src/x11shim/include",
    ]
    rows, excluded = scan(
        vendor, implemented_calls(Path(args.header).read_text()), includes
    )
    counts = {e: sum(r["effort"] == e for r in rows) for e in ("S", "M", "L", "XL")}
    intro = Path(args.intro).read_text().format(
        version=version,
        total=len(rows),
        excluded=len(excluded),
        **{f"n_{k.lower()}": v for k, v in counts.items()},
    )
    measured = Path(args.measured).read_text() if Path(args.measured).exists() else ""
    out = (
        intro
        + "\n"
        + measured
        + "\n## Suggested order for shim stage 2\n\n"
        + "Shim gaps across 2D hacks, ranked so gaps that block hacks\n"
        + "needing few additions come first.\n\n"
        + render_ranking(rank_missing(rows, 10))
        + "\n## All hacks\n\n"
        + render_table(rows)
        + "\n## Excluded files\n\n"
        + "These files in `hacks/` and `hacks/glx/` have no `XSCREENSAVER_MODULE`\n"
        + "entry point, so they are models, helper libraries or command-line\n"
        + "tools rather than screensavers:\n\n"
        + render_excluded(excluded)
    )
    Path(args.out).write_text(out)
    print(f"wrote {args.out}: {len(rows)} hacks ({len(excluded)} files excluded), {counts}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
#include <ctype.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "x11shim/xshim.h"

static const char *const *g_defaults;

void xshim_set_defaults(const char *const *defaults) { g_defaults = defaults; }

/* Finds "<.|*>name:<ws>value" and returns a pointer to the value, or NULL. */
static const char *lookup(const char *name) {
  if (!g_defaults) return NULL;
  size_t len = strlen(name);
  for (const char *const *p = g_defaults; *p; p++) {
    const char *s = *p;
    if (*s == '.' || *s == '*') s++;
    if (strncmp(s, name, len) != 0 || s[len] != ':') continue;
    s += len + 1;
    while (*s && isspace((unsigned char)*s)) s++;
    return s;
  }
  return NULL;
}

static const struct {
  const char *name;
  uint8_t r, g, b;
} kColours[] = {
    {"black", 0, 0, 0},     {"white", 255, 255, 255}, {"red", 255, 0, 0},
    {"green", 0, 255, 0},   {"blue", 0, 0, 255},      {"yellow", 255, 255, 0},
    {"magenta", 255, 0, 255}, {"cyan", 0, 255, 255},  {"orange", 255, 165, 0},
};

static void warn_missing(const char *name) {
  fprintf(stderr, "xshim: no default for resource '%s'\n", name);
}

int get_integer_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  return (int)strtol(v, NULL, 0);
}

double get_float_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  return strtod(v, NULL);
}

Bool get_boolean_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  if (!v) return False;
  return strncasecmp(v, "true", 4) == 0 || strncasecmp(v, "on", 2) == 0 ||
         strncasecmp(v, "yes", 3) == 0 || *v == '1';
}

char *get_string_resource(Display *dpy, const char *name, const char *cls) {
  (void)dpy;
  (void)cls;
  const char *v = lookup(name);
  return v ? strdup(v) : NULL;
}

unsigned long get_pixel_resource(Display *dpy, Colormap cmap, const char *name,
                                 const char *cls) {
  (void)dpy;
  (void)cmap;
  (void)cls;
  const char *v = lookup(name);
  if (!v) {
    warn_missing(name);
    return 0;
  }
  size_t tok = 0;
  while (v[tok] && !isspace((unsigned char)v[tok])) tok++;
  for (size_t i = 0; i < sizeof(kColours) / sizeof(kColours[0]); i++)
    if (strlen(kColours[i].name) == tok &&
        strncasecmp(v, kColours[i].name, tok) == 0)
      return rgb565(kColours[i].r, kColours[i].g, kColours[i].b);
  if (*v == '#' && strlen(v) >= 7) {
    unsigned r, g, b;
    if (sscanf(v + 1, "%2x%2x%2x", &r, &g, &b) == 3)
      return rgb565((uint8_t)r, (uint8_t)g, (uint8_t)b);
  }
  fprintf(stderr, "xshim: unknown colour '%s' for '%s'\n", v, name);
  return 0xFFFF;
}
/* Shim versions of the few xscreensaver utils helpers that hacks call.
 * Written for this project; not derived from xscreensaver's utils. */
#include <stdlib.h>

#include "colors.h"
#include "erase.h"
#include "hsv.h"

static double frand_unit(void) {
  return (double)random() / ((double)RAND_MAX + 1.0);
}

/* No wipe animation: clear the window and report that erasing is done. */
eraser_state *erase_window(Display *dpy, Window w, eraser_state *st) {
  (void)st;
  XClearWindow(dpy, w);
  return NULL;
}

void eraser_free(eraser_state *st) { (void)st; }

void make_random_colormap(Screen *screen, Visual *visual, Colormap cmap,
                          XColor *colors, int *ncolorsP, Bool bright_p,
                          Bool allocate_p, Bool *writable_pP, Bool verbose_p) {
  (void)screen;
  (void)visual;
  (void)cmap;
  (void)allocate_p;
  (void)verbose_p;
  if (writable_pP) *writable_pP = False;
  for (int i = 0; i < *ncolorsP; i++) {
    double s = bright_p ? 0.6 + frand_unit() * 0.4 : 0.2 + frand_unit() * 0.8;
    double v = bright_p ? 0.8 + frand_unit() * 0.2 : 0.5 + frand_unit() * 0.5;
    hsv_to_rgb((int)(frand_unit() * 360), s, v, &colors[i].red,
               &colors[i].green, &colors[i].blue);
    colors[i].flags = DoRed | DoGreen | DoBlue;
    colors[i].pixel = rgb565_from16(colors[i].red, colors[i].green, colors[i].blue);
  }
}

