  if (!r || runner_start(r, index) != 0) {
    fprintf(stderr, "bad hack index %d (have %d)\n", index, g_hack_count);
    return 1;
  }
  for (int i = 0; i < frames; i++) runner_step(r);
  FILE *f = fopen(argv[3], "wb");
  if (!f) return 1;
  fwrite(cv.px, sizeof(uint16_t), (size_t)cv.w * cv.h, f);
  fclose(f);
  runner_destroy(r);
  canvas_free(&cv);
  return 0;
}

